let _gsTimeout = null;
function globalSearch(q) {
  clearTimeout(_gsTimeout);
  const box = document.getElementById('global-search-results');
  if (!box) return;
  if (!q || q.length < 2) { box.classList.remove('open'); box.innerHTML=''; return; }
  _gsTimeout = setTimeout(() => {
    const ql = q.toLowerCase();
    const all = allRecords();
    const results = all.filter(r =>
      r[0].toLowerCase().includes(ql) ||
      (r[1]||'').toLowerCase().includes(ql) ||
      (r[3]||'').toLowerCase().includes(ql)
    ).slice(0,10);

    if (!results.length) {
      box.innerHTML='<div class="gs-item" style="color:var(--text3)">Nenhum resultado encontrado.</div>';
    } else {
      box.innerHTML = results.map(r=>`
        <div class="gs-item" onclick="gsOpen('${r[0]}')">
          <div class="gs-num">${r[0]}</div>
          <div class="gs-title">${(r[1]||'—').slice(0,60)}</div>
          <div class="gs-meta">${r[2]||'—'} · ${(r[3]||'—').replace(/,/g,' e ')} · <span class="pill ${statusPill(r[5])}" style="padding:1px 6px;font-size:10px">${r[5]}</span></div>
        </div>`).join('');
    }
    box.classList.add('open');
  }, 180);
}
function gsOpen(num) {
  document.getElementById('global-search-results').classList.remove('open');
  document.getElementById('global-search-box').value = '';
  openDetalhe(num);
}
// Close on outside click
document.addEventListener('click', e => {
  const wrap = document.getElementById('global-search-wrap');
  if (wrap && !wrap.contains(e.target))
    document.getElementById('global-search-results')?.classList.remove('open');
});

// ══════════════════════════════════════════════════════════════
// PAINEL OPERACIONAL
// ══════════════════════════════════════════════════════════════
function renderPainel() {
  const all    = allRecords();
  const closed = getClosedMap();
  const isCl   = r => r[5]==='Concluída'||r[5]==='Encerrado'||!!closed[r[0]];
  const abertos= all.filter(r=>!isCl(r));
  const hoje   = new Date().toISOString().slice(0,10);
  const inicioSemana = new Date(); inicioSemana.setDate(inicioSemana.getDate()-7);

  // KPIs
  const criticos  = abertos.filter(r=>(r[9]||r[10]||'')==='Urgente').length;
  const vencidos  = abertos.filter(r=>r[4]&&Math.floor((new Date()-new Date(r[4]+'T00:00'))/86400000)>7).length;
  const hoje_ab   = all.filter(r=>r[4]===hoje).length;
  const local     = getLocal();
  const hoje_enc  = Object.values(closed).filter(ci=>ci.encerradoEm?.slice(0,10)===hoje).length;

  // SLA: % encerrados dentro de 7 dias
  let slaOk=0, slaTotal=0;
  Object.entries(closed).forEach(([num,ci])=>{
    const rec=all.find(r=>r[0]===num);
    if(!rec||!rec[4]||!ci.encerradoEm) return;
    slaTotal++;
    const dias=Math.floor((new Date(ci.encerradoEm)-new Date(rec[4]+'T00:00'))/86400000);
    if(dias<=7) slaOk++;
  });
  const slaPct = slaTotal ? Math.round(slaOk/slaTotal*100) : 0;

  const setEl=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};
  setEl('op-criticos', criticos);
  setEl('op-vencidos',  vencidos);
  setEl('op-hoje',      hoje_ab);
  setEl('op-enc-hoje',  hoje_enc);
  setEl('op-sla',       slaPct+'%');
  const slaBar=document.getElementById('op-sla-bar');
  if(slaBar){slaBar.style.width=slaPct+'%';slaBar.style.background=slaPct>=90?'var(--green)':slaPct>=70?'var(--amber)':'var(--red)';}

  // Lista chamados críticos abertos (top 6)
  const listCrit = document.getElementById('op-list-criticos');
  if(listCrit){
    const urgentes = abertos.filter(r=>(r[9]||r[10]||'')==='Urgente').slice(0,6);
    const venc6    = abertos.filter(r=>r[4]&&Math.floor((new Date()-new Date(r[4]+'T00:00'))/86400000)>7).slice(0,6);
    const show     = urgentes.length ? urgentes : venc6;
    if(!show.length){ listCrit.innerHTML='<div style="color:var(--text3);padding:8px 0">Nenhum chamado crítico.</div>'; }
    else listCrit.innerHTML = show.map(r=>{
      const dias=r[4]?Math.floor((new Date()-new Date(r[4]+'T00:00'))/86400000):0;
      return `<div class="op-row" style="cursor:pointer" onclick="openDetalhe('${r[0]}')">
        <span class="td-num" style="font-size:11px">${r[0]}</span>
        <span style="flex:1;padding:0 8px;font-size:11px">${(r[1]||'').slice(0,30)}</span>
        <span style="color:${dias>7?'var(--red)':'var(--amber)'};font-size:11px">${dias}d</span>
      </div>`;
    }).join('');
  }

  // Ranking técnicos (esta semana)
  const rankEl = document.getElementById('op-ranking');
  if(rankEl){
    const isSemana = ts => ts && new Date(ts) >= inicioSemana;
    const rankMap  = {};
    Object.values(closed).filter(ci=>isSemana(ci.encerradoEm)).forEach(ci=>{
      const n=ci.encerradoPor||'Sistema'; rankMap[n]=(rankMap[n]||0)+1;
    });
    const rank=Object.entries(rankMap).sort((a,b)=>b[1]-a[1]).slice(0,5);
    const maxR=rank[0]?.[1]||1;
    rankEl.innerHTML = rank.length ? rank.map(([n,v],i)=>`
      <div class="op-row">
        <span style="font-weight:700;color:var(--text3);min-width:20px">${i+1}º</span>
        <span style="flex:1;padding:0 8px">${n.split(' ')[0]}</span>
        <span style="font-weight:700;color:var(--accent)">${v}</span>
        <div style="width:60px;height:4px;background:var(--border);border-radius:2px;margin-left:8px"><div style="width:${v/maxR*100}%;height:100%;background:var(--accent);border-radius:2px"></div></div>
      </div>`).join('') : '<div style="color:var(--text3);padding:8px 0">Sem dados nesta semana.</div>';
  }

  // Por sistema
  const sistEl = document.getElementById('op-sistemas');
  if(sistEl){
    const sistMap={};
    abertos.forEach(r=>{if(r[6])sistMap[r[6]]=(sistMap[r[6]]||0)+1;});
    const sist=Object.entries(sistMap).sort((a,b)=>b[1]-a[1]).slice(0,5);
    const maxS=sist[0]?.[1]||1;
    sistEl.innerHTML=sist.length?sist.map(([n,v])=>`
      <div class="op-row">
        <span style="flex:1;font-size:11px">${n}</span>
        <span style="font-weight:700;color:var(--text)">${v}</span>
        <div style="width:60px;height:4px;background:var(--border);border-radius:2px;margin-left:8px"><div style="width:${v/maxS*100}%;height:100%;background:var(--teal);border-radius:2px"></div></div>
      </div>`).join(''):'<div style="color:var(--text3);padding:8px">Sem chamados abertos.</div>';
  }

  // Tempo médio por técnico
  const tempoEl = document.getElementById('op-tempo-tecnico');
  if(tempoEl){
    const tempoMap={};
    Object.entries(closed).forEach(([num,ci])=>{
      const rec=all.find(r=>r[0]===num);
      if(!rec||!rec[4]||!ci.encerradoEm||!ci.encerradoPor)return;
      const dias=Math.floor((new Date(ci.encerradoEm)-new Date(rec[4]+'T00:00'))/86400000);
      if(dias<0)return;
      if(!tempoMap[ci.encerradoPor])tempoMap[ci.encerradoPor]={soma:0,cnt:0};
      tempoMap[ci.encerradoPor].soma+=dias;
      tempoMap[ci.encerradoPor].cnt++;
    });
    const tempo=Object.entries(tempoMap).map(([n,d])=>([n,Math.round(d.soma/d.cnt*10)/10])).sort((a,b)=>a[1]-b[1]).slice(0,5);
    tempoEl.innerHTML=tempo.length?tempo.map(([n,v])=>`
      <div class="op-row">
        <span style="flex:1">${n.split(' ')[0]}</span>
        <span style="font-weight:700;color:${v<=3?'var(--green)':v<=7?'var(--amber)':'var(--red)'}">${v}d</span>
        <span style="font-size:10px;color:var(--text3);margin-left:6px">tempo médio</span>
      </div>`).join(''):'<div style="color:var(--text3);padding:8px">Sem dados suficientes.</div>';
  }

  const upd=document.getElementById('op-updated');
  if(upd)upd.textContent=new Date().toLocaleTimeString('pt-BR');
}

// ══════════════════════════════════════════════════════════════
// IA LOCAL — sugestão de causas e soluções baseada no histórico
// ══════════════════════════════════════════════════════════════
function iaAnalisar() {
  const sintoma = (document.getElementById('ia-sintoma')?.value||'').toLowerCase().trim();
  const resEl   = document.getElementById('ia-resultado');
  if (!resEl) return;
  if (!sintoma) { resEl.innerHTML='<div style="color:var(--text3);font-size:12px">Digite um sintoma para analisar.</div>'; return; }

  resEl.innerHTML='<div class="ai-suggestion" style="opacity:.6">🤖 Analisando histórico…</div>';

  setTimeout(()=>{
    const all    = allRecords();
    const closed = getClosedMap();
    const kb     = getKB();

    // Find matching records by keyword overlap
    const words = sintoma.split(/\s+/).filter(w=>w.length>2);
    const scored = all.map(r=>{
      const text=(r[0]+' '+(r[1]||'')+' '+(r[2]||'')).toLowerCase();
      const score=words.reduce((s,w)=>s+(text.includes(w)?1:0),0);
      return {r, score};
    }).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,10);

    // Solutions from closedMap for matching records
    const solutions=[];
    scored.forEach(({r})=>{
      const ci=closed[r[0]];
      if(ci?.solucao) solutions.push({solucao:ci.solucao, materiais:ci.materiais||'', sistema:r[6]||''});
    });

    // KB matches
    const kbMatches=kb.filter(k=>{
      const kText=(k.problema+' '+k.solucao).toLowerCase();
      return words.some(w=>kText.includes(w));
    }).slice(0,3);

    // Most common systems in matches
    const sistCount={};
    scored.forEach(({r})=>{if(r[6])sistCount[r[6]]=(sistCount[r[6]]||0)+1;});
    const topSist=Object.entries(sistCount).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([s])=>s).join(', ');

    // Most common technicians for these types
    const techCount={};
    scored.forEach(({r})=>{
      const ci=closed[r[0]];
      if(ci?.encerradoPor)(ci.encerradoPor.split(',').forEach(t=>{t=t.trim();if(t)techCount[t]=(techCount[t]||0)+1;}));
    });
    const topTech=Object.entries(techCount).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([t])=>t.split(' ')[0]).join(', ');

    // Build suggestion
    let html='';
    if(!scored.length && !kbMatches.length){
      html='<div class="ai-suggestion">Nenhum histórico similar encontrado para este sintoma. Tente palavras diferentes.</div>';
    } else {
      html+='<div class="ai-suggestion">';
      html+=`<b>📊 Análise:</b> Encontrei <b>${scored.length}</b> chamados similares no histórico.<br>`;
      if(topSist) html+=`<b>📡 Sistema mais afetado:</b> ${topSist}<br>`;
      if(topTech) html+=`<b>👷 Técnicos experientes:</b> ${topTech}<br>`;

      if(solutions.length){
        html+='<br><b>💡 Soluções aplicadas anteriormente:</b><ul style="margin:4px 0 0 14px;padding:0">';
        [...new Set(solutions.map(s=>s.solucao))].slice(0,3).forEach(s=>{
          html+=`<li style="margin-bottom:3px">${s.slice(0,120)}${s.length>120?'…':''}</li>`;
        });
        html+='</ul>';
        const mats=[...new Set(solutions.map(s=>s.materiais).filter(Boolean))].slice(0,3);
        if(mats.length) html+=`<br><b>🔧 Materiais comuns:</b> ${mats.join(' · ')}`;
      }

      if(kbMatches.length){
        html+='<br><br><b>📚 Banco de Soluções:</b><ul style="margin:4px 0 0 14px;padding:0">';
        kbMatches.forEach(k=>{ html+=`<li style="margin-bottom:3px"><b>${k.problema}</b>: ${k.solucao.slice(0,100)}${k.solucao.length>100?'…':''}</li>`; });
        html+='</ul>';
      }
      html+='</div>';

      if(solutions.length){
        html+=`<button class="ai-chip" style="margin-top:8px" onclick="usarSugestaoIA('${(solutions[0]?.solucao||'').replace(/'/g,"\'").slice(0,200)}','${(solutions[0]?.materiais||'').replace(/'/g,"\'")}')">
          📋 Usar primeira sugestão no checklist
        </button>`;
      }
    }
    if(resEl) resEl.innerHTML=html;
  }, 400);
}

function usarSugestaoIA(solucao, materiais) {
  const s=document.getElementById('chk-solucao');
  const m=document.getElementById('chk-materiais');
  if(s) s.value=solucao;
  if(m && materiais) m.value=materiais;
  showToast('Sugestão da IA aplicada ao checklist!');
}


// ══════════════════════════════════════════════════════════════
// MÓDULO: EQUIPAMENTOS — Autocomplete + Validação
// Fonte: planilha equipamentos.xlsx (445 registros)
// Chaves: c=código, d=descrição, e=equipamento(concat), m=modelo, t=tipo, g=grupo, s=status
// ══════════════════════════════════════════════════════════════

let _equipFocusIdx = -1;   // keyboard nav index
let _equipValid    = false; // whether a valid equipment is selected

// ── Search: filter EQUIPAMENTOS by code or description
function equipSearch(q) {
  const drop  = document.getElementById('equip-dropdown');
  const clear = document.getElementById('equip-clear');
  const infoC = document.getElementById('equip-info-card');
  const selV  = document.getElementById('equip-selected-valid');

  if (clear) clear.className = q ? 'equip-clear-btn show' : 'equip-clear-btn';

  // If user is typing after a valid selection, invalidate it
  if (_equipValid) {
    _equipValid = false;
    if (selV) selV.value = '';
    if (infoC) infoC.className = 'equip-info-card';
  }

  if (!q || q.length < 1) {
    drop.className = 'equip-dropdown';
    drop.innerHTML = '';
    _equipFocusIdx = -1;
    return;
  }

  const ql = q.toLowerCase();
  // Search: code starts-with first, then description contains
  const exact   = EQUIPAMENTOS.filter(e => e.c.toLowerCase().startsWith(ql));
  const partial = EQUIPAMENTOS.filter(e =>
    !e.c.toLowerCase().startsWith(ql) &&
    (e.d.toLowerCase().includes(ql) || e.e.toLowerCase().includes(ql))
  );
  const results = [...exact, ...partial].slice(0, 30);

  if (!results.length) {
    drop.innerHTML = '<div class="equip-nofound">Nenhum equipamento encontrado para "' + q + '"</div>';
    drop.className = 'equip-dropdown open';
    return;
  }

  _equipFocusIdx = -1;
  drop.innerHTML = results.map((e, i) => `
    <div class="equip-item" data-idx="${i}" data-codigo="${e.c}"
      onmousedown="equipSelect(${JSON.stringify(e).replace(/"/g,'&quot;')})"
      onmouseover="equipHover(${i})">
      <div class="equip-item-code">${e.c}</div>
      <div class="equip-item-name">${e.d}</div>
      <div class="equip-item-meta">
        <span>${e.g || '—'}</span>
        <span>${e.m || '—'}</span>
        ${e.s !== 'Ativo' ? '<span class="equip-badge-inactive">INATIVO</span>' : ''}
      </div>
    </div>`).join('');
  drop.className = 'equip-dropdown open';
}

// ── Keyboard navigation (↑ ↓ Enter Escape)
function equipKeyNav(e) {
  const drop  = document.getElementById('equip-dropdown');
  const items = drop.querySelectorAll('.equip-item');
  if (!items.length) return;

  if (e.key === 'ArrowDown') {
    e.preventDefault();
    _equipFocusIdx = Math.min(_equipFocusIdx + 1, items.length - 1);
    equipHighlight(items);
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    _equipFocusIdx = Math.max(_equipFocusIdx - 1, 0);
    equipHighlight(items);
  } else if (e.key === 'Enter') {
    e.preventDefault();
    if (_equipFocusIdx >= 0 && items[_equipFocusIdx]) {
      items[_equipFocusIdx].dispatchEvent(new MouseEvent('mousedown'));
    }
  } else if (e.key === 'Escape') {
    drop.className = 'equip-dropdown';
    _equipFocusIdx = -1;
  }
}

function equipHighlight(items) {
  items.forEach((it, i) => {
    it.className = 'equip-item' + (i === _equipFocusIdx ? ' focused' : '');
  });
  if (items[_equipFocusIdx]) {
    items[_equipFocusIdx].scrollIntoView({ block: 'nearest' });
  }
}

function equipHover(idx) {
  _equipFocusIdx = idx;
  const drop  = document.getElementById('equip-dropdown');
  equipHighlight(drop.querySelectorAll('.equip-item'));
}

// ── Select: fill input + info card + hidden fields
function equipSelect(equip) {
  const input = document.getElementById('f-titulo');
  const drop  = document.getElementById('equip-dropdown');
  const clear = document.getElementById('equip-clear');
  const infoC = document.getElementById('equip-info-card');
  const selC  = document.getElementById('equip-selected-codigo');
  const selV  = document.getElementById('equip-selected-valid');

  // Fill the main input with the equipamento string (code + description)
  if (input) input.value = equip.e || (equip.c + ' ' + equip.d);

  // Close dropdown
  drop.className = 'equip-dropdown';
  drop.innerHTML = '';
  _equipFocusIdx = -1;

  // Fill info card
  const setEl = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v || '—'; };
  setEl('equip-info-codigo', equip.c);
  setEl('equip-info-modelo', equip.m);
  setEl('equip-info-grupo',  equip.g);
  setEl('equip-info-tipo',   equip.t);
  const statusEl = document.getElementById('equip-info-status');
  if (statusEl) {
    statusEl.textContent = equip.s;
    statusEl.style.color = equip.s === 'Ativo' ? 'var(--green)' : 'var(--amber)';
  }
  if (infoC) infoC.className = 'equip-info-card show';

  // Mark as valid selection
  _equipValid = true;
  if (selC) selC.value = equip.c;
  if (selV) selV.value = '1';
  if (clear) clear.className = 'equip-clear-btn show';
}

// ── Clear selection
function equipClear() {
  const input = document.getElementById('f-titulo');
  const drop  = document.getElementById('equip-dropdown');
  const clear = document.getElementById('equip-clear');
  const infoC = document.getElementById('equip-info-card');
  const selC  = document.getElementById('equip-selected-codigo');
  const selV  = document.getElementById('equip-selected-valid');

  if (input) { input.value = ''; input.focus(); }
  if (drop)  { drop.className = 'equip-dropdown'; drop.innerHTML = ''; }
  if (clear) clear.className = 'equip-clear-btn';
  if (infoC) infoC.className = 'equip-info-card';
  if (selC)  selC.value = '';
  if (selV)  selV.value = '';
  _equipValid = false;
  _equipFocusIdx = -1;
}

// ── Close dropdown when clicking outside
document.addEventListener('click', function(ev) {
  const wrap = document.querySelector('.equip-wrap');
  if (wrap && !wrap.contains(ev.target)) {
    const drop = document.getElementById('equip-dropdown');
    if (drop) drop.className = 'equip-dropdown';
    _equipFocusIdx = -1;
  }
});

// ── Reset autocomplete when form is reset
function resetEquipForm() {
  equipClear();
}


// ══════════════════════════════════════════════════════════════
// HISTÓRICO POR FROTA
// ══════════════════════════════════════════════════════════════
function renderFrotas() {
  const q       = (document.getElementById('fr-srch')?.value||'').toLowerCase();
  const fGrupo  = document.getElementById('fr-f-grupo')?.value||'';
  const fStatus = document.getElementById('fr-f-status')?.value||'';
  const fSort   = document.getElementById('fr-f-sort')?.value||'count';

  const all     = allRecords();
  const local   = getLocal();
  const closed  = getClosedMap();

  // Build frota → chamados map from MATCH_MAP + local records with equipCodigo
  const frotaMap = {}; // code -> [rec, ...]

  // Historical matches (MATCH_MAP)
  Object.entries(MATCH_MAP).forEach(([num, code]) => {
    const rec = all.find(r=>r[0]===num);
    if (!rec) return;
    if (!frotaMap[code]) frotaMap[code] = [];
    frotaMap[code].push(rec);
  });

  // New chamados from local records with equipCodigo
  local.forEach(lr => {
    if (!lr.equipCodigo) return;
    const code = lr.equipCodigo;
    const rec  = all.find(r=>r[0]===lr.num);
    if (!rec) return;
    if (!frotaMap[code]) frotaMap[code] = [];
    // Avoid duplicates (may already be in MATCH_MAP)
    if (!frotaMap[code].some(r=>r[0]===rec[0])) {
      frotaMap[code].push(rec);
    }
  });

  // Build display list with equip metadata
  let items = Object.entries(frotaMap).map(([code, recs]) => {
    const eq = EQUIP_IDX[code] || {d:code, m:'—', g:'—', s:'Ativo'};
    return { code, recs, d:eq.d, m:eq.m, g:eq.g, s:eq.s, count:recs.length };
  });

  // Filters
  if (q)       items=items.filter(x=>x.code.toLowerCase().includes(q)||x.d.toLowerCase().includes(q)||x.m.toLowerCase().includes(q));
  if (fGrupo)  items=items.filter(x=>x.g===fGrupo);
  if (fStatus) items=items.filter(x=>x.s===fStatus);

  // Sort
  if (fSort==='count')    items.sort((a,b)=>b.count-a.count);
  else if (fSort==='codigo')   items.sort((a,b)=>a.code.localeCompare(b.code));
  else if (fSort==='descricao')items.sort((a,b)=>a.d.localeCompare(b.d));

  // KPIs
  const allVinc  = Object.values(frotaMap).flat().length;
  const inativas = items.filter(x=>x.s!=='Ativo').length;
  const top      = items.sort((a,b)=>b.count-a.count)[0];
  const pct      = all.length ? Math.round(allVinc/all.length*100) : 0;
  const setEl=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};
  setEl('fr-total',     items.length.toLocaleString('pt-BR'));
  setEl('fr-chamados',  allVinc.toLocaleString('pt-BR'));
  setEl('fr-pct',       pct+'%');
  setEl('fr-top',       top ? top.code+' · '+top.d.slice(0,20) : '—');
  setEl('fr-inativas',  inativas.toLocaleString('pt-BR'));

  // Re-sort for display after KPI calc
  if (fSort==='count')    items.sort((a,b)=>b.count-a.count);
  else if (fSort==='codigo')   items.sort((a,b)=>a.code.localeCompare(b.code));
  else if (fSort==='descricao')items.sort((a,b)=>a.d.localeCompare(b.d));

  const tbody = document.getElementById('tbl-frotas');
  const empty = document.getElementById('fr-empty');
  if (!tbody) return;

  if (!items.length) {
    tbody.innerHTML='';
    if(empty) empty.style.display='block';
    return;
  }
  if(empty) empty.style.display='none';

  tbody.innerHTML = items.map(x=>`
    <tr>
      <td class="td-num">${x.code}</td>
      <td style="font-weight:600;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${x.d}</td>
      <td style="font-size:11px;color:var(--text3)">${x.m||'—'}</td>
      <td><span class="pill chip-blue">${x.g||'—'}</span></td>
      <td><span style="font-size:11px;font-weight:600;color:${x.s==='Ativo'?'var(--green)':'var(--amber)'}">${x.s}</span></td>
      <td style="text-align:center">
        <span style="background:var(--accent-light);color:var(--accent);padding:2px 9px;border-radius:12px;font-size:11px;font-weight:700">${x.count}</span>
      </td>
      <td>
        <button class="btn btn-ghost" style="font-size:11px;padding:3px 8px" onclick="verHistoricoFrota('${x.code}')">
          📋 Ver histórico
        </button>
      </td>
    </tr>`).join('');
}

function verHistoricoFrota(code) {
  const eq     = EQUIP_IDX[code] || {d:code, m:'—', g:'—', s:'—'};
  const all    = allRecords();
  const local  = getLocal();
  const closed = getClosedMap();

  // Gather all chamados for this frota
  const nums = new Set();
  Object.entries(MATCH_MAP).forEach(([n,c])=>{ if(c===code) nums.add(n); });
  local.forEach(lr=>{ if(lr.equipCodigo===code) nums.add(lr.num); });

  const recs = all.filter(r=>nums.has(r[0]));
  const isCl = r=>r[5]==='Concluída'||r[5]==='Encerrado'||!!closed[r[0]];
  const conc  = recs.filter(isCl).length;
  const aberto= recs.filter(r=>!isCl(r)).length;

  // Avg resolution time
  let somaD=0, cntD=0;
  recs.forEach(r=>{
    const ci=closed[r[0]];
    if(ci?.encerradoEm&&r[4]){
      const d=Math.floor((new Date(ci.encerradoEm)-new Date(r[4]+'T00:00'))/86400000);
      if(d>=0){somaD+=d;cntD++;}
    }
  });
  const avgD = cntD ? (somaD/cntD).toFixed(1)+'d' : '—';

  const setEl=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};
  setEl('fr-detail-title', code+' · '+eq.d);
  setEl('fr-detail-sub',   eq.g+' · '+eq.m+(eq.s?' · '+eq.s:''));
  setEl('fr-d-total',  recs.length);
  setEl('fr-d-conc',   conc);
  setEl('fr-d-aberto', aberto);
  setEl('fr-d-tempo',  avgD);

  document.getElementById('tbl-fr-detail').innerHTML = recs
    .sort((a,b)=>b[4]?.localeCompare(a[4]||'')||0)
    .map(r=>`<tr style="cursor:pointer" onclick="openDetalhe('${r[0]}')">
      <td class="td-num">${r[0]}</td>
      <td style="max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${r[1]||'—'}</td>
      <td style="font-family:var(--font-mono);font-size:11px">${r[4]?r[4].split('-').reverse().join('/'):' —'}</td>
      <td><span class="pill ${statusPill(r[5])}">${r[5]}</span></td>
      <td style="font-size:11px">${(r[3]||'—').replace(/,/g,' e ')}</td>
    </tr>`).join('');

  document.getElementById('fr-detail-card').style.display='block';
  document.getElementById('fr-detail-card').scrollIntoView({behavior:'smooth'});
}


// ══════════════════════════════════════════════════════════════
// MENU PRINCIPAL — Portal de Tecnologia SC
// Módulos: campo (atual), irrigacao, chips
// Para adicionar novo módulo: (1) criar sec-X, (2) adicionar card no menu HTML,
// (3) chamar abrirModulo('X'), (4) adicionar a MODULOS_CONFIG
// ══════════════════════════════════════════════════════════════

const MODULOS_CONFIG = {
  campo:    { label:'Chamados de Campo',       cor:'campo',    secao:'dashboard' },
  irrigacao:{ label:'Chamados de Irrigação',   cor:'irrigacao',secao:'irrigacao' },
  chips:    { label:'Chips de Abastecimento',  cor:'chips',    secao:'chips'     },
};

let _moduloAtivo = null;

// ── Exibir Menu Principal
function mostrarMenu() {
  const overlay = document.getElementById('menu-overlay');
  if (!overlay) return;
  overlay.classList.add('show');
  // position:fixed + z-index:490 covers .app — no visibility change needed

  // Esconder botão voltar ao portal
  const backBtn = document.getElementById('menu-back-btn');
  if (backBtn) backBtn.classList.remove('show');

  // Atualizar info do usuário e data
  const u = currentUser();
  const lbl = document.getElementById('menu-user-label');
  if (lbl && u) lbl.textContent = u.nome + ' · ' + (PERFIL_LABEL[u.perfil]||u.perfil);

  const fd = document.getElementById('menu-footer-date');
  if (fd) fd.textContent = new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'});

  // Remove badge de módulo da topbar
  const existingBadge = document.getElementById('topbar-module-badge');
  if (existingBadge) existingBadge.remove();

  _moduloAtivo = null;
}

// ── Abrir módulo específico
function abrirModulo(id) {
  const cfg = MODULOS_CONFIG[id];
  if (!cfg) return;

  // Esconde menu
  const overlay = document.getElementById('menu-overlay');
  if (overlay) overlay.classList.remove('show');

  // Mostra botão voltar ao portal
  const backBtn = document.getElementById('menu-back-btn');
  if (backBtn) backBtn.classList.add('show');

  // Adiciona badge de módulo ativo na topbar
  const existingBadge = document.getElementById('topbar-module-badge');
  if (existingBadge) existingBadge.remove();
  if (id !== 'campo') {
    const badge = document.createElement('span');
    badge.id = 'topbar-module-badge';
    badge.className = 'module-badge ' + id;
    badge.textContent = cfg.label;
    const tl = document.querySelector('.topbar-left');
    if (tl) tl.appendChild(badge);
  }

  _moduloAtivo = id;

  // Navigate to the module's home section
  if (id === 'campo') {
    // Show full sidebar nav for campo
    document.querySelector('.sidebar')?.style.removeProperty('display');
    showSection('dashboard', document.querySelector('.nav-item'));
  } else if (id === 'irrigacao') {
    // For irrigation/chips: show minimal nav (just portal back button)
    showSection('irrigacao', null);
  } else if (id === 'chips') {
    showSection('chips', null);
  }
}

// ── Voltar ao Menu
function voltarMenu() {
  mostrarMenu();
}


// ══════════════════════════════════════════════════════════════
// NAV GROUP — collapsible sidebar menus
// ══════════════════════════════════════════════════════════════
function toggleNavGroup(id, toggleEl) {
  const sub = document.getElementById(id);
  if (!sub) return;
  const isOpen = sub.classList.contains('open');
  // Close all groups first
  document.querySelectorAll('.nav-sub.open').forEach(s => {
    s.classList.remove('open');
    s.previousElementSibling?.classList.remove('open');
  });
  if (!isOpen) {
    sub.classList.add('open');
    toggleEl.classList.add('open');
  }
}

// ══════════════════════════════════════════════════════════════
// EQUIPAMENTOS — full catalogue view (from EQUIPAMENTOS xlsx)
// ══════════════════════════════════════════════════════════════
function renderEquipamentos() {
  const q        = (document.getElementById('eq-srch')?.value||'').toLowerCase();
  const fTipo    = document.getElementById('eq-f-tipo')?.value||'';
  const fFazenda = document.getElementById('eq-f-fazenda')?.value||'';
  const fStat    = document.getElementById('eq-f-status')?.value||'';
  const fSemCad  = document.getElementById('eq-f-sem-cad')?.checked||false;

  // Base list: EQUIPAMENTOS xlsx merged with local cadastro overrides
  const cadMap   = getCadEq();                              // {frota: {...campos extras}}
  const baseList = typeof EQUIPAMENTOS!=='undefined' ? EQUIPAMENTOS : [];

  // Build unified list: xlsx record + local overrides merged
  let items = baseList.map(e => {
    const cad = cadMap[e.c] || {};
    return {
      frota:       e.c,
      descricao:   e.d,
      modelo:      cad.modelo      || e.m || '',
      fabricante:  cad.fabricante  || '',
      ano:         cad.ano         || '',
      tipo:        cad.tipo        || e.g || '',
      horimetro:   cad.horimetro   || '',
      fazenda:     cad.fazenda     || '',
      cultura:     cad.cultura     || '',
      responsavel: cad.responsavel || '',
      status:      cad.status      || e.s || 'Ativo',
      patrimonio:  cad.patrimonio  || '',
      serie:       cad.serie       || '',
      obs:         cad.obs         || '',
      temCad:      !!cadMap[e.c],
    };
  });

  // Chamados count map
  const chCount = {};
  if (typeof MATCH_MAP!=='undefined') Object.values(MATCH_MAP).forEach(c=>{chCount[c]=(chCount[c]||0)+1;});
  getLocal().forEach(lr=>{ if(lr.equipCodigo) chCount[lr.equipCodigo]=(chCount[lr.equipCodigo]||0)+1; });

  // Filters
  if (q)        items=items.filter(e=>e.frota.toLowerCase().includes(q)||e.descricao.toLowerCase().includes(q)||(e.modelo||'').toLowerCase().includes(q)||(e.fabricante||'').toLowerCase().includes(q)||(e.patrimonio||'').toLowerCase().includes(q));
  if (fTipo)    items=items.filter(e=>e.tipo===fTipo);
  if (fFazenda) items=items.filter(e=>e.fazenda===fFazenda);
  if (fStat)    items=items.filter(e=>e.status===fStat);
  if (fSemCad)  items=items.filter(e=>!e.temCad);

  // KPIs
  const all    = baseList;
  const comCad = Object.keys(cadMap).length;
  const setEl  = (id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};
  setEl('eq-total',   all.length.toLocaleString('pt-BR'));
  setEl('eq-ativos',  all.filter(e=>(cadMap[e.c]?.status||e.s)==='Ativo').length.toLocaleString('pt-BR'));
  setEl('eq-inativos',all.filter(e=>(cadMap[e.c]?.status||e.s)!=='Ativo').length.toLocaleString('pt-BR'));
  setEl('eq-com-ch',  new Set(Object.values(typeof MATCH_MAP!=='undefined'?MATCH_MAP:{})).size.toLocaleString('pt-BR'));
  setEl('eq-com-cad', comCad.toLocaleString('pt-BR'));

  const tbody=document.getElementById('tbl-equipamentos');
  const empty=document.getElementById('eq-empty');
  if(!tbody) return;

  if(!items.length){
    tbody.innerHTML='';
    if(empty) empty.style.display='block';
    document.getElementById('eq-pag').innerHTML='';
    return;
  }
  if(empty) empty.style.display='none';

  // Pagination
  const PAGE=25;
  if(typeof _eqPage==='undefined') window._eqPage=1;
  const total=items.length;
  const pageItems=items.slice((_eqPage-1)*PAGE,_eqPage*PAGE);

  const statusColor=s=>s==='Ativo'?'var(--green)':s==='Manutenção'?'var(--amber)':'var(--text3)';

  tbody.innerHTML=pageItems.map(e=>{
    const cnt=chCount[e.frota]||0;
    const hasData=e.patrimonio||e.fabricante||e.ano||e.horimetro||e.fazenda||e.responsavel;
    return `<tr>
      <td class="td-num">${e.frota}</td>
      <td style="font-weight:600;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${e.descricao}">${e.descricao}</td>
      <td style="font-size:11px;font-family:var(--font-mono)">${e.patrimonio||'<span style="color:var(--border2)">—</span>'}</td>
      <td style="font-size:11px">${e.modelo||'—'}</td>
      <td style="font-size:11px">${e.fabricante||'<span style="color:var(--border2)">—</span>'}</td>
      <td style="font-size:11px;text-align:center">${e.ano||'<span style="color:var(--border2)">—</span>'}</td>
      <td><span class="pill chip-blue" style="font-size:10px">${e.tipo||'—'}</span></td>
      <td style="font-size:11px;text-align:right">${e.horimetro?Number(e.horimetro).toLocaleString('pt-BR')+'h':'<span style="color:var(--border2)">—</span>'}</td>
      <td style="font-size:11px">${e.fazenda||'<span style="color:var(--border2)">—</span>'}</td>
      <td style="font-size:11px">${e.cultura||'<span style="color:var(--border2)">—</span>'}</td>
      <td style="font-size:11px">${e.responsavel||'<span style="color:var(--border2)">—</span>'}</td>
      <td><span style="font-size:11px;font-weight:600;color:${statusColor(e.status)}">${e.status}</span></td>
      <td style="text-align:center">${cnt?`<span style="background:var(--accent-light);color:var(--accent);padding:2px 8px;border-radius:12px;font-size:11px;font-weight:700;cursor:pointer" onclick="verHistoricoFrota('${e.frota}')">${cnt}</span>`:'<span style="color:var(--border2);font-size:11px">—</span>'}</td>
      <td style="white-space:nowrap">
        <button class="btn btn-ghost" style="padding:3px 8px;font-size:11px" onclick="abrirFormEq('${e.frota}')">✏️ Editar</button>
      </td>
    </tr>`;
  }).join('');

  // Pagination bar
  const pages=Math.ceil(total/PAGE);
  const pag=document.getElementById('eq-pag');
  if(pag&&pages>1){
    let btns=`<span style="font-size:11px;color:var(--text3)">${total.toLocaleString('pt-BR')} equipamentos</span> `;
    for(let p=1;p<=pages;p++){
      if(p===1||p===pages||Math.abs(p-_eqPage)<=1){
        btns+=`<button class="pag-btn${p===_eqPage?' active':''}" onclick="eqGotoPage(${p})">${p}</button>`;
      } else if(Math.abs(p-_eqPage)===2){
        btns+=`<span style="color:var(--text3);padding:0 4px">…</span>`;
      }
    }
    pag.innerHTML=btns;
  } else if(pag){
    pag.innerHTML=total>0?`<span style="font-size:11px;color:var(--text3)">${total.toLocaleString('pt-BR')} equipamentos</span>`:'';
  }
}

function eqGotoPage(p){window._eqPage=p;renderEquipamentos();}

// ══════════════════════════════════════════════════════════════
// TÉCNICOS — dashboard per-technician
// ══════════════════════════════════════════════════════════════
function renderTecnicos() {
  const q       = (document.getElementById('tec-srch')?.value||'').toLowerCase();
  const fArea   = document.getElementById('tec-f-area')?.value||'';
  const periodo = document.getElementById('tec-f-periodo')?.value||'tudo';
  const view    = document.getElementById('tec-f-view')?.value||'cards';

  // Toggle views
  document.getElementById('tec-view-cards').style.display  = view==='cards'  ? 'block':'none';
  document.getElementById('tec-view-tabela').style.display = view==='tabela' ? 'block':'none';

  const all    = allRecords();
  const closed = getClosedMap();
  const cadTec = getCadTec();

  // Period cutoff
  const cutoff = periodo!=='tudo'
    ? new Date(Date.now()-Number(periodo)*86400000).toISOString().slice(0,10)
    : '0000-00-00';

  // Build stats map from chamados data (using resp field + tecnico field from local)
  const statsMap = {};  // apelido -> {total, conc, aberto, tempos[]}
  all.forEach(rec => {
    if ((rec[4]||'') < cutoff) return;
    // Responsáveis (resp field — multi-value comma separated)
    (rec[3]||'').split(',').map(n=>n.trim()).filter(Boolean).forEach(nome => {
      if (!statsMap[nome]) statsMap[nome]={total:0,conc:0,aberto:0,tempos:[]};
      statsMap[nome].total++;
      const ci=closed[rec[0]];
      if (ci) {
        statsMap[nome].conc++;
        if (rec[4]&&ci.encerradoEm) {
          const d=Math.floor((new Date(ci.encerradoEm)-new Date(rec[4]+'T00:00'))/86400000);
          if (d>=0&&d<365) statsMap[nome].tempos.push(d);
        }
      } else { statsMap[nome].aberto++; }
    });
    // Also credit local tecnico field if set
    const lr=getLocal().find(r=>r.num===rec[0]);
    if (lr?.tecnico && !statsMap[lr.tecnico]) {
      statsMap[lr.tecnico]={total:0,conc:0,aberto:0,tempos:[]};
    }
  });

  // Merge cadastro + stats into unified tech list
  // Start with cadastro entries
  const cadKeys=Object.keys(cadTec);
  const allNames=new Set([...cadKeys,...Object.keys(statsMap)]);

  let tecs=[...allNames].map(key=>{
    const cad=cadTec[key]||{};
    const st=statsMap[cad.apelido||key]||statsMap[key]||{total:0,conc:0,aberto:0,tempos:[]};
    return {
      id:      key,
      nome:    cad.nome    || key,
      apelido: cad.apelido || key,
      telefone:cad.telefone|| '',
      email:   cad.email   || '',
      area:    cad.area    || '',
      cargo:   cad.cargo   || '',
      status:  cad.status  || 'Ativo',
      admissao:cad.admissao|| '',
      obs:     cad.obs     || '',
      temCad:  !!cadTec[key],
      total:   st.total,
      conc:    st.conc,
      aberto:  st.aberto,
      tempos:  st.tempos,
    };
  });

  // Filters
  if (q)     tecs=tecs.filter(t=>t.nome.toLowerCase().includes(q)||t.apelido.toLowerCase().includes(q)||(t.email||'').toLowerCase().includes(q)||(t.area||'').toLowerCase().includes(q));
  if (fArea) tecs=tecs.filter(t=>t.area===fArea);

  tecs.sort((a,b)=>b.total-a.total);

  // ── KPIs
  const setEl=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};
  setEl('tec-total',    tecs.length);
  setEl('tec-top',      tecs[0]?.apelido.split(' ')[0]||'—');
  const allTempos=tecs.flatMap(t=>t.tempos);
  setEl('tec-avg-tempo', allTempos.length?(allTempos.reduce((a,b)=>a+b,0)/allTempos.length).toFixed(1)+'d':'—');
  const slaOk=tecs.reduce((s,t)=>s+t.tempos.filter(d=>d<=7).length,0);
  const slaTot=tecs.reduce((s,t)=>s+t.tempos.length,0);
  setEl('tec-sla',      slaTot?Math.round(slaOk/slaTot*100)+'%':'—');
  setEl('tec-pendentes',tecs.reduce((s,t)=>s+t.aberto,0));

  const colors=['var(--accent)','var(--teal)','var(--green)','var(--purple)','var(--amber)','var(--red)'];
  const statusColor=s=>s==='Ativo'?'var(--green)':s==='Férias'?'var(--amber)':s==='Afastado'?'var(--amber)':'var(--text3)';
  const statusLabel=s=>({'Ativo':'🟢 Ativo','Inativo':'⚫ Inativo','Férias':'🏖 Férias','Afastado':'⚠ Afastado'}[s]||s);

  // ── VIEW: CARDS
  if (view==='cards') {
    const grid=document.getElementById('tec-cards-grid');
    if (!grid) return;
    if (!tecs.length){grid.innerHTML='<div style="grid-column:1/-1;text-align:center;color:var(--text3);padding:40px">Nenhum técnico encontrado.</div>';return;}
    grid.innerHTML=tecs.map((t,i)=>{
      const avgT=t.tempos.length?(t.tempos.reduce((a,b)=>a+b,0)/t.tempos.length).toFixed(1):'—';
      const slaP=t.tempos.length?Math.round(t.tempos.filter(d=>d<=7).length/t.tempos.length*100):0;
      const color=colors[i%colors.length];
      const initials=t.apelido.split(' ').slice(0,2).map(w=>w[0]||'').join('').toUpperCase()||'?';
      const pct=t.total>0?Math.min(100,Math.round(t.conc/t.total*100)):0;
      return `<div class="card" style="padding:0;overflow:hidden">
        <!-- Header do card -->
        <div style="padding:16px 16px 14px;display:flex;align-items:flex-start;gap:12px">
          <div style="width:46px;height:46px;border-radius:50%;background:${color}18;border:2px solid ${color};
            display:flex;align-items:center;justify-content:center;
            font-size:15px;font-weight:800;color:${color};flex-shrink:0;letter-spacing:-.02em">${initials}</div>
          <div style="min-width:0;flex:1">
            <div style="font-size:13px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${t.nome}</div>
            ${t.cargo?`<div style="font-size:11px;color:var(--text3);margin-top:1px">${t.cargo}</div>`:''}
            <div style="display:flex;gap:8px;margin-top:5px;flex-wrap:wrap">
              ${t.area?`<span style="font-size:10px;font-weight:600;background:${color}18;color:${color};padding:1px 7px;border-radius:20px">${t.area}</span>`:''}
              <span style="font-size:10px;font-weight:600;color:${statusColor(t.status)}">${statusLabel(t.status)}</span>
            </div>
          </div>
          <button class="btn btn-ghost" style="padding:3px 8px;font-size:11px;flex-shrink:0"
            onclick="abrirFormTec('${t.id}')">✏️</button>
        </div>

        <!-- Contatos -->
        ${(t.telefone||t.email)?`<div style="padding:0 16px 10px;display:flex;gap:12px;flex-wrap:wrap">
          ${t.telefone?`<a href="tel:${t.telefone}" style="font-size:11px;color:var(--text3);display:flex;align-items:center;gap:4px;text-decoration:none">📞 ${t.telefone}</a>`:''}
          ${t.email?`<a href="mailto:${t.email}" style="font-size:11px;color:var(--accent);display:flex;align-items:center;gap:4px;text-decoration:none">✉️ ${t.email}</a>`:''}
        </div>`:''}

        <!-- Divisor -->
        <div style="height:1px;background:var(--border)"></div>

        <!-- Stats -->
        <div style="padding:12px 16px;display:grid;grid-template-columns:repeat(3,1fr);gap:6px;text-align:center">
          <div>
            <div style="font-size:20px;font-weight:800;color:var(--text);font-family:var(--font-mono);line-height:1">${t.total}</div>
            <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-top:2px">Total</div>
          </div>
          <div>
            <div style="font-size:20px;font-weight:800;color:var(--green);font-family:var(--font-mono);line-height:1">${t.conc}</div>
            <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-top:2px">Concluídos</div>
          </div>
          <div>
            <div style="font-size:20px;font-weight:800;color:var(--amber);font-family:var(--font-mono);line-height:1">${t.aberto}</div>
            <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-top:2px">Pendentes</div>
          </div>
        </div>

        <!-- Barra de progresso -->
        <div style="padding:0 16px 8px">
          <div style="height:4px;background:var(--border);border-radius:2px;overflow:hidden">
            <div style="height:100%;border-radius:2px;background:${color};width:${pct}%;transition:width .8s"></div>
          </div>
          <div style="display:flex;justify-content:space-between;margin-top:4px">
            <span style="font-size:10px;color:var(--text3)">${pct}% conclusão</span>
            <span style="font-size:10px;color:var(--text3)">⏱ ${avgT}${avgT!=='—'?'d':''} médio</span>
          </div>
        </div>

        <!-- SLA -->
        <div style="margin:0 16px 14px;padding:6px 10px;background:var(--surface2);border:1px solid var(--border);border-radius:var(--radius-sm);display:flex;justify-content:space-between;align-items:center">
          <span style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3)">SLA ≤7 dias</span>
          <span style="font-size:13px;font-weight:800;color:${slaP>=90?'var(--green)':slaP>=70?'var(--amber)':'var(--red)'}">${slaP?slaP+'%':'—'}</span>
        </div>
      </div>`;
    }).join('');
  }

  // ── VIEW: TABELA
  if (view==='tabela') {
    const tbody=document.getElementById('tbl-tecnicos');
    const empty=document.getElementById('tec-empty');
    if (!tbody) return;
    if (!tecs.length){tbody.innerHTML='';if(empty)empty.style.display='block';return;}
    if(empty) empty.style.display='none';
    tbody.innerHTML=tecs.map(t=>{
      const avgT=t.tempos.length?(t.tempos.reduce((a,b)=>a+b,0)/t.tempos.length).toFixed(1)+'d':'—';
      return `<tr>
        <td style="font-weight:600">${t.nome}</td>
        <td style="font-family:var(--font-mono);font-size:11px">${t.apelido||'—'}</td>
        <td>${t.area?`<span class="pill chip-blue" style="font-size:10px">${t.area}</span>`:'—'}</td>
        <td style="font-size:11px;color:var(--text3)">${t.cargo||'—'}</td>
        <td style="font-size:11px">${t.telefone?`<a href="tel:${t.telefone}" style="color:var(--accent)">${t.telefone}</a>`:'—'}</td>
        <td style="font-size:11px">${t.email?`<a href="mailto:${t.email}" style="color:var(--accent)">${t.email}</a>`:'—'}</td>
        <td><span style="font-size:11px;font-weight:600;color:${statusColor(t.status)}">${t.status}</span></td>
        <td style="text-align:center;font-family:var(--font-mono);font-weight:700">${t.total}</td>
        <td style="text-align:center;font-family:var(--font-mono);font-weight:700;color:var(--green)">${t.conc}</td>
        <td style="text-align:center;font-family:var(--font-mono);font-weight:700;color:var(--amber)">${t.aberto}</td>
        <td style="font-family:var(--font-mono);font-size:11px">${avgT}</td>
        <td style="white-space:nowrap">
          <button class="btn btn-ghost" style="padding:3px 8px;font-size:11px" onclick="abrirFormTec('${t.id}')">✏️ Editar</button>
        </td>
      </tr>`;
    }).join('');
  }
}

// ══════════════════════════════════════════════════════════════
// CONFIGURAÇÕES — render settings page
// ══════════════════════════════════════════════════════════════
function renderConfig() {
  // Tema atual
  const tema = localStorage.getItem('chm_theme')||'light';
  const temaEl = document.getElementById('cfg-tema-val');
  if (temaEl) temaEl.textContent = tema === 'dark' ? '🌙 Escuro' : '☀️ Claro';

  // Stats
  const setEl=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};
  setEl('cfg-total-ch', allRecords().length.toLocaleString('pt-BR')+' chamados');
  setEl('cfg-total-eq', (typeof EQUIPAMENTOS!=='undefined'?EQUIPAMENTOS.length:0).toLocaleString('pt-BR')+' equipamentos');

  // Load email config into form
  const cfg = typeof emailService !== 'undefined' && emailService.config ? emailService.config : {};
  const prov = document.getElementById('cfg-email-provider');
  const tok  = document.getElementById('cfg-email-token');
  const frm  = document.getElementById('cfg-email-from');
  if (prov) prov.value   = cfg.provider||'none';
  if (tok)  tok.value    = cfg.token||'';
  if (frm)  frm.value    = cfg.from||'';
}

function salvarEmailConfig() {
  const provider = document.getElementById('cfg-email-provider')?.value||'none';
  const token    = document.getElementById('cfg-email-token')?.value||'';
  const from     = document.getElementById('cfg-email-from')?.value||'';
  localStorage.setItem('chm_email_cfg', JSON.stringify({provider,token,from}));
  if (typeof emailService !== 'undefined') {
    emailService.config = {provider,token,from};
  }
  const st = document.getElementById('cfg-email-status');
  if (st) { st.textContent='✓ Configurações salvas.'; st.style.color='var(--green)'; }
  showToast('Configurações de e-mail salvas!');
}

function limparDadosLocais() {
  if (!confirm('Isso irá remover todos os chamados, encerramentos, KB e peças criados localmente. Os dados históricos (3.155 chamados) serão preservados. Continuar?')) return;
  ['chm_local_v1','chm_closed_v1','chm_kb_v1','chm_pecas_v1','chm_movs_v1','chm_events_v1'].forEach(k=>localStorage.removeItem(k));
  refreshAfterAction();
  showToast('Dados locais removidos.');
}

function exportarCSV() {
  const all = allRecords();
  const header = 'Número,Título,Cultura,Responsável,Data,Status,Sistema';
  const body = all.map(r=>[r[0],`"${(r[1]||'').replace(/"/g,'""')}"`,r[2]||'',r[3]||'',r[4]||'',r[5]||'',r[6]||''].join(',')).join(String.fromCharCode(10));
  const a=document.createElement('a');
  a.href='data:text/csv;charset=utf-8,﻿'+encodeURIComponent(header+String.fromCharCode(10)+body);
  a.download='chamados_santa_colomba.csv';a.click();
}


// ── Quick filter from KPI card click
function applyStatusFilter(status) {
  // Navigate to chamados section
  showSection('chamados', document.getElementById('nav-dashboard'));
  // Apply the filter after a brief render tick
  setTimeout(()=>{
    const sel = document.getElementById('f-status');
    if (sel) {
      sel.value = status;
      applyFilters();
    }
    // Highlight the correct nav item
    document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
    document.querySelector('[onclick*="chamados"]')?.classList.add('active');
  }, 50);
}


// ══════════════════════════════════════════════════════════════
// EQUIPAMENTOS — CRUD (cadastro local sobrepõe planilha xlsx)
// ══════════════════════════════════════════════════════════════
const CADASTRO_EQ_KEY = 'chm_cad_eq_v1';
function getCadEq()  { try { return JSON.parse(localStorage.getItem(CADASTRO_EQ_KEY)||'{}'); } catch { return {}; } }
function saveCadEq(v){ localStorage.setItem(CADASTRO_EQ_KEY, JSON.stringify(v)); }

// ── Autocomplete inline no formulário (busca no EQUIPAMENTOS xlsx)
let _eqFormFocusIdx = -1;
function equipFormSearch(q, dropId, codeId) {
  const drop = document.getElementById(dropId);
  if (!drop) return;
  if (!q || q.length < 1) { drop.className='equip-dropdown'; drop.innerHTML=''; _eqFormFocusIdx=-1; return; }
  const ql = q.toLowerCase();
  const results = (typeof EQUIPAMENTOS!=='undefined'?EQUIPAMENTOS:[])
    .filter(e=>e.c.toLowerCase().startsWith(ql)||e.d.toLowerCase().includes(ql)||e.e.toLowerCase().includes(ql))
    .slice(0,20);
  if(!results.length){ drop.innerHTML='<div class="equip-nofound">Nenhum resultado</div>'; drop.className='equip-dropdown open'; return; }
  _eqFormFocusIdx=-1;
  drop.innerHTML=results.map((e,i)=>`
    <div class="equip-item" data-idx="${i}"
      onmousedown="equipFormSelect(${JSON.stringify(e).replace(/"/g,'&quot;')},'${dropId}','${codeId}')"
      onmouseover="_eqFormFocusIdx=${i};equipFormHighlight(document.getElementById('${dropId}').querySelectorAll('.equip-item'))">
      <div class="equip-item-code">${e.c}</div>
      <div class="equip-item-name">${e.d}</div>
      <div class="equip-item-meta"><span>${e.g||'—'}</span><span>${e.m||'—'}</span></div>
    </div>`).join('');
  drop.className='equip-dropdown open';
}

function equipFormKeyNav(ev, dropId, codeId) {
  const drop=document.getElementById(dropId);
  const items=drop?.querySelectorAll('.equip-item');
  if(!items?.length) return;
  if(ev.key==='ArrowDown'){ev.preventDefault();_eqFormFocusIdx=Math.min(_eqFormFocusIdx+1,items.length-1);equipFormHighlight(items);}
  else if(ev.key==='ArrowUp'){ev.preventDefault();_eqFormFocusIdx=Math.max(_eqFormFocusIdx-1,0);equipFormHighlight(items);}
  else if(ev.key==='Enter'){ev.preventDefault();if(_eqFormFocusIdx>=0)items[_eqFormFocusIdx].dispatchEvent(new MouseEvent('mousedown'));}
  else if(ev.key==='Escape'){drop.className='equip-dropdown';_eqFormFocusIdx=-1;}
}

function equipFormHighlight(items){
  items.forEach((it,i)=>it.className='equip-item'+(i===_eqFormFocusIdx?' focused':''));
  items[_eqFormFocusIdx]?.scrollIntoView({block:'nearest'});
}

function equipFormSelect(equip, dropId, codeId) {
  document.getElementById('eq-frota').value    = equip.e||(equip.c+' '+equip.d);
  document.getElementById('eq-frota-code').value = equip.c;
  document.getElementById('eq-descricao').value  = equip.d;
  document.getElementById('eq-modelo').value     = equip.m||'';
  // Auto-fill tipo from grupo
  const tipoMap={'TRATOR':'TRATOR','COLHEDORA':'COLHEDORA','PULVERIZADOR':'PULVERIZADOR',
    'CAMINHÃO':'CAMINHÃO','SEMEADORA':'SEMEADORA','VEÍCULOS LEVES':'VEÍCULOS LEVES'};
  const tipoEl=document.getElementById('eq-tipo');
  if(tipoEl && tipoMap[equip.g]) tipoEl.value=tipoMap[equip.g];
  const drop=document.getElementById(dropId);
  if(drop){drop.className='equip-dropdown';drop.innerHTML='';}
  _eqFormFocusIdx=-1;
}

// ── Abrir formulário (novo ou edição)
function abrirFormEq(frota) {
  const card=document.getElementById('form-eq-card');
  if(!card) return;

  // Reset all fields
  ['eq-frota','eq-patrimonio','eq-descricao','eq-serie','eq-modelo','eq-fabricante',
   'eq-ano','eq-horimetro','eq-obs','eq-edit-id','eq-frota-code'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.value='';
  });
  ['eq-tipo','eq-status','eq-fazenda','eq-cultura','eq-responsavel'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.selectedIndex=0;
  });
  document.getElementById('eq-erro').style.display='none';

  if(frota){
    // Edit mode — load existing data
    document.getElementById('form-eq-title').textContent='Editar Equipamento';
    document.getElementById('eq-edit-id').value=frota;

    // Load from xlsx base
    const base=(typeof EQUIPAMENTOS!=='undefined'?EQUIPAMENTOS:[]).find(e=>e.c===frota);
    if(base){
      document.getElementById('eq-frota').value   = base.e||(base.c+' '+base.d);
      document.getElementById('eq-frota-code').value = base.c;
      document.getElementById('eq-descricao').value  = base.d;
      document.getElementById('eq-modelo').value     = base.m||'';
    }

    // Override with local cadastro data
    const cad=getCadEq()[frota]||{};
    const setVal=(id,v)=>{const el=document.getElementById(id);if(el&&v!==undefined)el.value=v;};
    setVal('eq-patrimonio', cad.patrimonio);
    setVal('eq-serie',      cad.serie);
    setVal('eq-modelo',     cad.modelo||(base?.m||''));
    setVal('eq-fabricante', cad.fabricante);
    setVal('eq-ano',        cad.ano);
    setVal('eq-horimetro',  cad.horimetro);
    setVal('eq-obs',        cad.obs);
    const setSel=(id,v)=>{const el=document.getElementById(id);if(el&&v)el.value=v;};
    setSel('eq-tipo',       cad.tipo||(base?.g||''));
    setSel('eq-status',     cad.status);
    setSel('eq-fazenda',    cad.fazenda);
    setSel('eq-cultura',    cad.cultura);
    setSel('eq-responsavel',cad.responsavel);
  } else {
    document.getElementById('form-eq-title').textContent='Novo Equipamento';
    document.getElementById('eq-status').value='Ativo';
  }

  card.style.display='block';
  card.scrollIntoView({behavior:'smooth', block:'start'});
}

function fecharFormEq() {
  const card=document.getElementById('form-eq-card');
  if(card) card.style.display='none';
}

// ── Salvar
function salvarEq() {
  const frota  = document.getElementById('eq-frota-code').value.trim()
               || document.getElementById('eq-frota').value.trim().split(' ')[0];
  const erroEl = document.getElementById('eq-erro');

  if(!frota){ erroEl.style.display='block'; erroEl.textContent='⛔ Selecione um equipamento da lista (Frota é obrigatório).'; return; }

  const get=(id)=>document.getElementById(id)?.value?.trim()||'';

  const cad=getCadEq();
  cad[frota]={
    frota,
    patrimonio:  get('eq-patrimonio'),
    serie:       get('eq-serie'),
    modelo:      get('eq-modelo'),
    fabricante:  get('eq-fabricante'),
    ano:         get('eq-ano'),
    tipo:        get('eq-tipo'),
    horimetro:   get('eq-horimetro'),
    status:      get('eq-status')||'Ativo',
    fazenda:     get('eq-fazenda'),
    cultura:     get('eq-cultura'),
    responsavel: get('eq-responsavel'),
    obs:         get('eq-obs'),
    atualizadoEm: new Date().toISOString(),
    atualizadoPor: currentUser()?.nome||'Sistema',
  };
  saveCadEq(cad);
  fecharFormEq();
  window._eqPage=1;
  renderEquipamentos();
  showToast('✓ Equipamento salvo no cadastro!');
  audit('editou', `Equipamento ${frota} cadastrado/atualizado`, frota);
}

// ── Close autocomplete on outside click
document.addEventListener('click', ev=>{
  const wrap=document.getElementById('eq-frota-wrap');
  if(wrap&&!wrap.contains(ev.target)){
    const drop=document.getElementById('eq-frota-drop');
    if(drop) drop.className='equip-dropdown';
    _eqFormFocusIdx=-1;
  }
});


