// REGISTRO DE EVENTOS NA TIMELINE
// ══════════════════════════════════════════════════════════════
let _pendingEvtType = null;

// Event type configs: which need a detail input?
const EVT_NEEDS_INPUT = {
  iniciou:          false,
  peca_solicitada:  true,   // ask: which part?
  peca_recebida:    true,   // confirm: which part arrived
  obs:              true,   // free text
};
const EVT_LABELS = {
  iniciou:          'Iniciar Atendimento',
  peca_solicitada:  'Solicitar Peça',
  peca_recebida:    'Peça Recebida',
  obs:              'Observação',
};
const EVT_PLACEHOLDERS = {
  peca_solicitada: 'Descreva a peça solicitada (ex: Fusível 5A, Cabo USB…)',
  peca_recebida:   'Confirme a peça recebida (ex: Fusível 5A recebido)',
  obs:             'Digite a observação…',
};
// Status that each event sets on the local record
const EVT_STATUS_CHANGE = {
  iniciou:         'Em Atendimento',
  peca_solicitada: 'Aguardando Peça',
  peca_recebida:   'Em Atendimento',   // resumes after part arrives
};

function registrarEvento(type) {
  _pendingEvtType = type;
  const wrap  = document.getElementById('det-evt-input-wrap');
  const input = document.getElementById('det-evt-input');

  if (EVT_NEEDS_INPUT[type]) {
    if (wrap)  { wrap.style.display='block'; }
    if (input) {
      input.placeholder = EVT_PLACEHOLDERS[type] || 'Descreva…';
      input.value = '';
      input.focus();
    }
  } else {
    // No input needed — register immediately
    confirmarEvento();
  }
}

function confirmarEvento() {
  const type  = _pendingEvtType;
  if (!type)  return;
  const num   = detCurrentNum;
  if (!num)   return;
  const u     = currentUser();
  const input = document.getElementById('det-evt-input');
  const detail = (input?.value || '').trim();

  if (EVT_NEEDS_INPUT[type] && !detail) {
    showToast('⚠ Descreva o evento antes de confirmar.');
    input?.focus();
    return;
  }

  // Register the event in the log
  addEvent(num, type, u?.nome||'Sistema', detail);

  // Update status on local record if applicable
  const newStatus = EVT_STATUS_CHANGE[type];
  if (newStatus) {
    const local = getLocal();
    const idx   = local.findIndex(r => r.num === num);
    if (idx >= 0) {
      local[idx].status = newStatus;
      saveLocal(local);
    } else {
      // Historical record — create local override for status
      const rec = allRecords().find(r => r[0] === num);
      if (rec) {
        local.push({
          num: rec[0], titulo: rec[1], cultura: rec[2],
          resp: rec[3], data: rec[4], status: newStatus, bucket: rec[6],
        });
        saveLocal(local);
      }
    }
  }

  // Audit
  const labelMap = EVT_LABELS;
  audit(type, `${labelMap[type]||type}: ${detail}`, num);

  // Reset UI
  cancelarEvento();
  showToast(`✓ Evento "${EVT_LABELS[type]||type}" registrado`);

  // Refresh timeline in open modal
  refreshAfterAction();
  if (document.getElementById('modal-detalhe')?.classList.contains('open')) {
    openDetalhe(num);
  }
}

function cancelarEvento() {
  _pendingEvtType = null;
  const wrap  = document.getElementById('det-evt-input-wrap');
  const input = document.getElementById('det-evt-input');
  if (wrap)  wrap.style.display = 'none';
  if (input) input.value = '';
}


// ══════════════════════════════════════════════════════════════
// FIREBASE SYNC LAYER
// Each save function calls localStorage (sync) then Firestore (async)
// The system always works offline; Firestore is best-effort
// ══════════════════════════════════════════════════════════════

// ── Guard: only sync if Firebase is loaded
function _fbReady() { return typeof window.fsSave === 'function'; }

// ── CHAMADOS (local records) — array → Firestore 'chamados' collection
// Override saveLocal to also push to Firestore
const _saveLocalOrig = saveLocal;
saveLocal = function(arr) {
  _saveLocalOrig(arr);
  if (!_fbReady()) return;
  arr.forEach(rec => {
    if (!rec.num) return;
    const { fotos, ...recNoFotos } = rec; // fotos (base64) too large for Firestore
    window.fsSave('chamados', rec.num, recNoFotos).catch(()=>{});
  });
};

// ── ENCERRAMENTOS — object → Firestore 'encerramentos'
const _saveClosedOrig = saveClosed;
saveClosed = function(obj) {
  _saveClosedOrig(obj);
  if (!_fbReady()) return;
  Object.entries(obj).forEach(([num, ci]) => {
    window.fsSave('encerramentos', num, ci).catch(()=>{});
  });
};

// ── KB — array → Firestore 'kb'
const _saveKBOrig = saveKB;
saveKB = function(arr) {
  _saveKBOrig(arr);
  if (!_fbReady()) return;
  arr.forEach(k => {
    if (!k.id) return;
    window.fsSave('kb', k.id, k).catch(()=>{});
  });
};

// ── PEÇAS — array → Firestore 'pecas'
const _savePecasOrig = savePecas;
savePecas = function(arr) {
  _savePecasOrig(arr);
  if (!_fbReady()) return;
  arr.forEach(p => {
    if (!p.id) return;
    window.fsSave('pecas', p.id, p).catch(()=>{});
  });
};

// ── MOVIMENTAÇÕES — array → Firestore 'movimentacoes'
const _saveMovsOrig = saveMovs;
saveMovs = function(arr) {
  _saveMovsOrig(arr);
  if (!_fbReady()) return;
  arr.forEach(m => {
    if (!m.id) return;
    window.fsSave('movimentacoes', m.id, m).catch(()=>{});
  });
};

// ── EVENTOS por chamado — object → Firestore 'events'
const _saveEventsOrig = saveEvents;
saveEvents = function(obj) {
  _saveEventsOrig(obj);
  if (!_fbReady()) return;
  Object.entries(obj).forEach(([num, evs]) => {
    window.fsSave('events', num, { num, eventos: evs }).catch(()=>{});
  });
};

// ── AUDITORIA — array → Firestore 'auditoria' (last entry only, to avoid large docs)
const _saveAuditOrig = saveAudit;
saveAudit = function(arr) {
  _saveAuditOrig(arr);
  if (!_fbReady()) return;
  const last = arr[arr.length-1];
  if (!last) return;
  const id = 'log_' + Date.now();
  window.fsSave('auditoria', id, last).catch(()=>{});
};

// ── CADASTRO EQUIPAMENTOS — object → Firestore 'cad_eq'
const _saveCadEqOrig = saveCadEq;
saveCadEq = function(obj) {
  _saveCadEqOrig(obj);
  if (!_fbReady()) return;
  Object.entries(obj).forEach(([frota, data]) => {
    window.fsSave('cad_eq', frota, data).catch(()=>{});
  });
};

// ── CADASTRO TÉCNICOS — object → Firestore 'cad_tec'
const _saveCadTecOrig = saveCadTec;
saveCadTec = function(obj) {
  _saveCadTecOrig(obj);
  if (!_fbReady()) return;
  Object.entries(obj).forEach(([key, data]) => {
    window.fsSave('cad_tec', key, data).catch(()=>{});
  });
};

// ── USUÁRIOS — array → Firestore 'usuarios'
const _saveUsersOrig = saveUsers;
saveUsers = function(arr) {
  _saveUsersOrig(arr);
  if (!_fbReady()) return;
  arr.forEach(u => {
    if (!u.id) return;
    // Omit senha (security) — never send passwords to Firestore
    const { senha, ...uSafe } = u;
    window.fsSave('usuarios', u.id, uSafe).catch(()=>{});
  });
};

// ── Trigger full sync after login
function fbSyncAfterLogin() {
  if (!_fbReady()) return;
  setTimeout(() => {
    if (typeof window.fsSyncAll === 'function') {
      window.fsSyncAll().then(() => {
        console.log('[Firebase] Sync pós-login concluído');
      });
    }
  }, 500); // small delay so UI is fully ready
}


// ══════════════════════════════════════════════════════════════
// FIREBASE — funções do painel de configurações
// ══════════════════════════════════════════════════════════════

async function fbManualSync() {
  const log=document.getElementById('cfg-fb-log');
  const st=document.getElementById('cfg-fb-status');
  if(log) log.textContent='⏳ Sincronizando com o Firebase…';
  if(st)  st.textContent='Sincronizando…';
  if (!_fbReady()) {
    if(log) log.textContent='⚠ Firebase não disponível.';
    if(st)  { st.textContent='Offline'; st.style.color='var(--red)'; }
    return;
  }
  try {
    await window.fsSyncAll();
    const now=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
    if(log) log.textContent=`✓ Sync concluído às ${now}`;
    if(st)  { st.textContent='🟢 Online'; st.style.color='var(--green)'; }
    showToast('Firebase sincronizado com sucesso!');
  } catch(e) {
    if(log) log.textContent=`⚠ Erro: ${e.message}`;
    if(st)  { st.textContent='🔴 Erro'; st.style.color='var(--red)'; }
  }
}

async function fbExportFirestore() {
  const log=document.getElementById('cfg-fb-log');
  if(log) log.textContent='⏳ Enviando dados locais para o Firebase…';
  if (!_fbReady()) { if(log) log.textContent='⚠ Firebase não disponível.'; return; }

  let count=0;
  try {
    // Push all local chamados
    const local=getLocal();
    for (const rec of local) {
      if (!rec.num) continue;
      const { fotos, ...recSafe } = rec;
      await window.fsSave('chamados', rec.num, recSafe);
      count++;
    }
    // Push closed map
    const closed=getClosedMap();
    for (const [num,ci] of Object.entries(closed)) {
      await window.fsSave('encerramentos', num, ci);
      count++;
    }
    // Push KB, peças, movs, cad_eq, cad_tec
    for (const k of getKB())    { if(k.id) { await window.fsSave('kb',k.id,k); count++; } }
    for (const p of getPecas())  { if(p.id) { await window.fsSave('pecas',p.id,p); count++; } }
    for (const m of getMovs())   { if(m.id) { await window.fsSave('movimentacoes',m.id,m); count++; } }
    const ceq=getCadEq();
    for (const [k,v] of Object.entries(ceq)) { await window.fsSave('cad_eq',k,v); count++; }
    const ctec=getCadTec();
    for (const [k,v] of Object.entries(ctec)) { await window.fsSave('cad_tec',k,v); count++; }

    const now=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
    if(log) log.textContent=`✓ ${count} registros enviados às ${now}`;
    showToast(`✓ ${count} registros exportados para o Firebase!`);
  } catch(e) {
    if(log) log.textContent=`⚠ Erro no envio: ${e.message}`;
    showToast('⚠ Erro ao exportar para o Firebase.');
  }
}

